const inr = (n: number) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number.isFinite(n) ? n : 0);
function emi(p: number, annual: number, months: number) { const r = annual / 1200; return months <= 0 ? 0 : r === 0 ? p / months : p * r * (1 + r) ** months / ((1 + r) ** months - 1); }
function amortizationSchedule(principal: number, annualRate: number, months: number, payment: number) {
  let balance = principal;

  return Array.from({ length: months }, (_, index) => {
    const interest = balance * annualRate / 1200;
    const principalPaid = Math.min(balance, Math.max(payment - interest, 0));
    balance = Math.max(balance - principalPaid, 0);

    return { month: index + 1, payment: principalPaid + interest, principal: principalPaid, interest, balance };
  });
}
