  const calculatorSuitePage = <><section className="page-hero"><span className="eyebrow">Planning tools</span><h1>Make the numbers<br/><em>easier to compare.</em></h1><p>Use these independent estimates to explore fixed-term repayment scenarios. They are not lender quotes or approvals.</p></section><section className="section resource-directory"><div className="resource-link-grid">{calculatorRoutes.map(([slug,name,description])=><article className="resource-link-card" key={slug}><span className="eyebrow">Illustrative calculator</span><h2>{name}</h2><p>{description}</p>{link(`/calculators/${slug}`,'Open calculator →','text-link')}</article>)}<article className="resource-link-card"><span className="eyebrow">Illustrative calculator</span><h2>Balance transfer savings</h2><p>Compare remaining payments with a new rate, same remaining tenure and transfer costs.</p>{link('/calculators/balance-transfer','Open calculator →','text-link')}</article></div></section>{cta()}</>;
  const specializedCalculatorPage = calculatorPreset ? <><section className="page-hero"><div className="breadcrumb">{link('/','Home')} <span>/</span> {link('/calculators','Calculators')} <span>/</span> Estimate</div><span className="eyebrow">Illustrative planning tool</span><h1>{calculatorPreset[1]}<em>.</em></h1><p>{calculatorPreset[2]}</p></section><section className="section calculator-page">{calculator()}{calculatorSlug==='tenure-comparison' && <div className="compare-cards tenure-comparison">{[36,60,84].map(term=><article key={term}><span className="eyebrow">{term/12} year term · {rate.toFixed(1)}% illustrative</span><h2>{inr(emi(amount,rate,term))}<small> / month</small></h2><p>Estimated total interest <b>{inr(Math.max(emi(amount,rate,term)*term-amount,0))}</b></p></article>)}</div>}</section>{cta()}</> : null;
  const balanceTransferPage = <><section className="page-hero"><div className="breadcrumb">{link('/','Home')} <span>/</span> {link('/calculators','Calculators')}</div><span className="eyebrow">Compare estimated remaining cost</span><h1>Would a transfer<br/><em>change your total?</em></h1><p>Compare your current balance at its current annual rate with a new illustrative rate over the same remaining tenure. Add estimated transfer fees.</p></section><section className="section calculator-page"><div className="compare-controls"><label>Outstanding balance<input aria-label="Outstanding balance" type="number" min="0" value={amount} onChange={event=>setAmount(Math.max(0,+event.target.value))}/></label><label>Remaining tenure (months)<input aria-label="Remaining tenure in months" type="number" min="1" max="360" value={months} onChange={event=>setMonths(Math.max(1,Math.min(360,+event.target.value)))}/></label><label>Current annual rate (%)<input aria-label="Current annual rate" type="number" min="0" max="40" step="0.1" value={existingRate} onChange={event=>setExistingRate(Math.max(0,Math.min(40,+event.target.value)))}/></label><label>New illustrative annual rate (%)<input aria-label="New illustrative annual rate" type="number" min="0" max="40" step="0.1" value={newRate} onChange={event=>setNewRate(Math.max(0,Math.min(40,+event.target.value)))}/></label><label>Estimated transfer fees<input aria-label="Estimated transfer fees" type="number" min="0" value={transferFees} onChange={event=>setTransferFees(Math.max(0,+event.target.value))}/></label></div><div className="compare-cards"><article><span className="eyebrow">Current loan · {existingRate.toFixed(1)}%</span><h2>{inr(emi(amount,existingRate,months))}<small> / month</small></h2><p>Estimated remaining payments <b>{inr(emi(amount,existingRate,months)*months)}</b></p></article><article><span className="eyebrow">Illustrative transfer · {newRate.toFixed(1)}%</span><h2>{inr(emi(amount,newRate,months))}<small> / month</small></h2><p>Estimated payments plus fees <b>{inr(emi(amount,newRate,months)*months+transferFees)}</b></p></article></div><p className="assumption-note"><b>Estimated difference after fees: {inr(emi(amount,existingRate,months)*months-(emi(amount,newRate,months)*months+transferFees))}</b><br/>This estimate assumes the same outstanding principal and remaining tenure. It excludes lender charges and conditions beyond the fee entered. A lower rate does not guarantee savings or lender approval.</p></section>{cta()}</>;  const defaultFaqs: Array<[string, string]> = [['What does a DSA do?', 'A Direct Selling Agent helps connect prospective customers with a lending institution and may assist with information and application steps.'], [`Does ${companyName} approve loans?`, 'No. ${companyName} is a loan assistance business, not a lender. The financial institution makes every lending decision.'], ['What documents may be required?', 'Requirements vary by product and lender. Common requests may include identity, address, income and vehicle information.'], ['How is an EMI calculated?', 'It depends on principal, interest rate and tenure. Try our illustrative calculator.'], ['Is approval guaranteed?', 'No. All applications are assessed by the lender against its own criteria.'], ['Will you ask me for an OTP or password?', 'No. Never share an OTP, PIN, password or full card details with anyone claiming to help with a loan.'], ['How is my information handled?', 'Enquiry information should be used to respond to your request, subject to our privacy notice and configured systems.']];  const faqItems: Array<[string, string]> = publishedFaqs.length ? publishedFaqs.map(item => [item.question, item.answer]) : defaultFaqs;  const faqPage = <><section className="page-hero"><span className="eyebrow">We believe in clear answers</span><h1>Questions, meet<br/><em>clarity.</em></h1><p>Some helpful context for your loan assistance journey.</p></section><section className="section faq-page"><div className="faq-list">{faqItems.map(([q,a])=><details key={q}><summary>{q}<span>＋</span></summary><p>{a}</p></details>)}</div></section>{cta()}</>;  const businessContactDetails = <section className="business-contact-card"><span className="eyebrow">{companyName} · {businessConfig?.tagline ?? 'Financial Services'}</span><h2>Talk to our team.</h2>{businessConfig?.proprietor && <p>Proprietor: {businessConfig.proprietor}</p>}<div className="business-contact-links">{businessConfig?.phone && <a href={`tel:+${businessConfig.phone.replace(/\D/g, '')}`}>Primary mobile: {businessConfig.phone}</a>}{businessConfig?.officePhone && <a href={`tel:+${businessConfig.officePhone.replace(/\D/g, '')}`}>Office: {businessConfig.officePhone}</a>}{businessConfig?.email && <a href={`mailto:${businessConfig.email}`}>{businessConfig.email}</a>}{businessConfig?.whatsapp && whatsappHref() && <a className="button whatsapp-contact-button" href={whatsappHref()!} target="_blank" rel="noopener noreferrer">Chat on WhatsApp ↗</a>}</div>{businessConfig?.address && <address>{businessConfig.address}<br/>{businessConfig.city}<br/>{businessConfig.state} – {businessConfig.postalCode}, India</address>}{businessConfig?.directionsUrl && <a className="text-link" href={businessConfig.directionsUrl} target="_blank" rel="noopener noreferrer">Get directions in Google Maps ↗</a>}{businessConfig?.grievanceEmail && <p>Grievance contact: <a href={`mailto:${businessConfig.grievanceEmail}`}>{businessConfig.grievanceEmail}</a></p>}</section>;
  const contactPage = <><section className="page-hero"><div className="breadcrumb">{link('/','Home')} <span>/</span> Contact</div><span className="eyebrow">A real conversation starts with a hello</span><h1>We’re here<br/><em>to help.</em></h1><p>Contact {companyName} for financial services and loan assistance, or request a callback. Choose the channel that works for you.</p></section><section className="section contact-grid"><div className="contact-intro"><span className="eyebrow">Connect with us</span><h2>Let’s talk about<br/><em>what comes next.</em></h2><p>Use the secure form to request guidance or a callback. We do not ask for OTPs, passwords, PAN, Aadhaar or bank credentials.</p><div className="contact-note"><b>Privacy first</b><p>Your contact details and message are stored encrypted and used to respond to your request.</p></div>{businessContactDetails}</div><div className="contact-form-panel"><span className="eyebrow">Send a message</span><h3>How can we help?</h3><ContactMessageForm companyName={companyName}/></div></section>{cta()}</>;  const aboutPage = <><section className="page-hero"><span className="eyebrow">{businessConfig?.tagline ?? 'Financial Services'}</span><h1>Finance made<br/><em>simpler.</em></h1><p>{companyName} is a financial services and Direct Selling Agent (DSA) loan-assistance business based in Raipur, Chhattisgarh. We help customers understand currently supported financing services and the application process.</p></section><section className="section detail-grid"><div className="detail-main"><span className="eyebrow">Our approach</span><h2>Clarity is a good<br/><em>place to start.</em></h2><p>We help people understand financing options, gather questions and navigate the application process with applicable lending partners. We believe people deserve straightforward information and the time to decide what feels right for them.</p><p>We are not a bank or lender. Every loan decision, rate, fee and disbursement is determined by the financial institution.</p>{businessConfig?.proprietor && <p>Proprietor: <strong>{businessConfig.proprietor}</strong></p>}</div><aside className="detail-aside"><span className="aside-number">WHAT GUIDANCE MEANS</span><h3>Listen. Explain. Support.</h3><p>We aim to be responsive, transparent and respectful of every customer’s choices.</p>{businessConfig?.phone && <a href={`tel:+${businessConfig.phone.replace(/\D/g, '')}`}>Call {businessConfig.phone}</a>}</aside></section>{businessContactDetails}{cta()}</>;  const legalPage = <><section className="page-hero"><span className="eyebrow">{companyName}</span><h1>{title}<em>.</em></h1><p>Last updated: November 2026 · Draft for review before publication</p></section><section className="section legal-copy"><h2>Our role</h2><p>{companyName} provides financial services and DSA loan assistance. We are not the lender. A lending institution independently decides whether to offer a facility and determines applicable eligibility, rates, fees, terms and disbursement.</p><h2>Information and estimates</h2><p>Website content and calculator results are general information for planning. They do not constitute a loan offer, approval, financial advice or guarantee. Verify all terms directly with the lending institution before proceeding.</p><h2>Your choices and personal information</h2><p>Only provide information through the enquiry process when you wish to be contacted. Do not send OTPs, PINs, passwords or unnecessary sensitive documents. Contact information is provided below so you can reach the business through your preferred channel.</p><h2>Questions or concerns</h2><p>For questions about this website, privacy notice, or a service request, contact {companyName} using the official details below. Grievance contact details are shown only if separately configured for that purpose.</p>{businessContactDetails}</section>{cta()}</>;  const resourcesPage = <><section className="page-hero"><span className="eyebrow">Good information travels far</span><h1>Make sense of<br/><em>the details.</em></h1><p>Original educational guides to help you feel more prepared for a financing conversation.</p></section><section className="section news-list-section"><div className="news-list">{publishedEducation.map(article=><article className="news-row" key={article.slug}><div className="news-thumb"><span>SAHU<br/>LEARN</span></div><div><div className="news-meta">Financial learning<i/> Sahu Enterprises</div><h2>{article.title}</h2><p>{article.excerpt}</p>{link(`/education/${article.slug}`,'Read the article →')}</div></article>)}{Object.entries(guides).map(([slug,guide])=><article className="news-row" key={slug}><div className="news-thumb"><span>SAHU<br/>GUIDE</span></div><div><div className="news-meta">{guide.category}<i/> Original Sahu Enterprises guide</div><h2>{guide.title}</h2><p>{guide.intro}</p>{link(`/resources/${slug}`,'Read the guide →')}</div></article>)}</div></section>{cta()}</>;  const resourceSlug = path.split('/').pop() ?? '';
